function calc(){let a=minutes($('start').value),b=minutes($('end').value),br=Number($('breaks').value),h=(b-a-br)/60;$('calculatedHours').textContent=num(Number.isFinite(h)&&h>0?h:0);return {a,b,br,h}}
function entryValid(e){return e.date&&Number.isFinite(e.begin)&&Number.isFinite(e.finish)&&e.finish<=1440&&e.finish>e.begin&&Number.isFinite(e.breaks)&&e.breaks>=0&&e.breaks<e.finish-e.begin&&e.notes.trim()}
function saveEntry(e){if(!entryValid(e)){notify('invalid');return false}if(absent(e.person,e.date)){notify('absentDay');return false}if(entries.some(r=>r.person===e.person&&r.date===e.date&&r.begin<e.finish&&e.begin<r.finish)){notify('overlap');return false}entries.push({...e,id:uid(),hours:(e.finish-e.begin-e.breaks)/60,status:'approved',category:typeOfHour,approvedAt:new Date().toISOString()});logAction('Time entry saved',`${e.date} · ${person(e.person).name} · ${project(e.project).name} · ${typeOfHour}`);persist();$('reviewDate').value=e.date;render();notify('saved');return true}
function saveManual(){const c=calc();saveEntry({person:profile,project:$('project').value,date:$('date').value,begin:c.a,finish:c.b,breaks:c.br,notes:$('notes').value})}
function startTimer(){if(timer){notify('timerBusy');return}timer={person:profile,project:$('project').value,since:Date.now()};localStorage.setItem('standel_v03_timer',JSON.stringify(timer));updateTimer()}
