function recordHtml(r,allowDelete=false){const p=project(r.project);return `<div class="record" style="--project-color:${p.color}"><div><b>${safe(person(r.person).name)}</b><small><span class="dot"></span>${safe(p.name)} · ${safe(r.date)}</small><small>${clock(r.begin)}–${clock(r.finish)} · ${safe(r.notes)}</small><span class="badge">✓ ${safe(t('approved'))}</span></div><div><b>${num(r.hours)} h</b>${allowDelete?`<br><button class="btn tiny secondary" data-edit-entry="${safe(r.id)}" style="margin-top:8px">✎ ${safe(u('edit'))}</button> <button class="btn tiny secondary" data-kind="entry" data-id="${safe(r.id)}" style="margin-top:8px">${safe(t('delete'))}</button>`:''}</div></div>`}
