function saveAbsence(){const a={id:uid(),person:profile,from:$('absenceFrom').value,to:$('absenceTo').value,type:$('absenceType').value,notes:$('absenceNotes').value.trim()};if(!a.from||!a.to||a.to<a.from){notify('missingDate','absenceMessage');return}if((fromDate(a.to)-fromDate(a.from))/86400000>365){notify('missingDate','absenceMessage');return}if(absences.some(x=>x.person===profile&&a.from<=x.to&&x.from<=a.to)){notify('absenceOverlap','absenceMessage');return}if(entries.some(e=>e.person===profile&&dateIn(e.date,a.from,a.to))){notify('absenceWork','absenceMessage');return}absences.push(a);persist();calendarMonth=fromDate(a.from);calendarMonth.setDate(1);render();notify('absenceSaved','absenceMessage')}
