function refreshDropdowns(){const prevProject=$('project').value,prevProfile=profile,prevFilter=$('employeeFilter').value;const active=people.filter(x=>!x.archived),activeSites=projects.filter(x=>!x.archived);if(!active.some(x=>x.id===profile))profile=active[0]?.id||people[0]?.id||'';$('profile').innerHTML=people.map(x=>`<option value="${safe(x.id)}">${safe(x.name)}${x.archived?' (архив)':''}</option>`).join('');$('profile').value=prevProfile&&people.some(x=>x.id===prevProfile)?prevProfile:profile;$('project').innerHTML=activeSites.map(x=>`<option value="${safe(x.id)}">${safe(x.name)}</option>`).join('');$('project').value=activeSites.some(x=>x.id===prevProject)?prevProject:activeSites[0]?.id||'';$('employeeFilter').innerHTML=`<option value="all">${safe(t('everyone'))}</option>`+people.map(x=>`<option value="${safe(x.id)}">${safe(x.name)}</option>`).join('');$('employeeFilter').value=people.some(x=>x.id===prevFilter)?prevFilter:'all'}
