function projectOption(){return projects.filter(p=>!p.archived).map(p=>`<option value="${safe(p.id)}">${safe(p.name)}</option>`).join('')}
function peopleOption(){return people.filter(p=>!p.archived).map(p=>`<option value="${safe(p.id)}">${safe(p.name)}</option>`).join('')}
