function tableHTML(headers,rows){return `<div class="table-scroller"><table class="v4table"><thead><tr>${headers.map(h=>`<th>${safe(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`}
